  var alpha = falloff * 0.15;
  var color = mix(vec3f(0.68, 0.68, 0.71), vec3f(0.75, 0.80, 0.77) + light * 0.25, 0.7);
  color = mix(color, vec3f(0.91, 0.86, 0.98) + light * 0.09, light.b * 0.4);
